cd /home/daniel/ui-sandbox/src/main/frontend/src/app/features/people; python3 - <<'EOF'
f='people-list.ts'
s=open(f).read()
a='''              <td data-testid="rollup-moor-total">{{ moorTotal() }}</td>
              <td colspan="7"></td>
            </tr>
'''
s=s.replace(a,a+'''            <tr>
              <th scope="row" colspan="42">Moor top</th>
              <td data-testid="rollup-moor-top">{{ moorTop() ?? 'n/a' }}</td>
              <td colspan="7"></td>
            </tr>
''',1)
b='''    trimmedTotal((this.people() ?? []).map((p) => ({ value: p.moor, hold: p.hold }))),
  );
'''
assert b in s
s=s.replace(b,b+'''
  // The highest moor among the people not on hold, skipping n/a; n/a when there is none.
  protected readonly moorTop = computed(() => {
    const values = (this.people() ?? [])
      .filter((p) => !p.hold)
      .map((p) => p.moor)
      .filter((v): v is number => v !== null);
    return values.length === 0 ? null : Math.max(...values);
  });
''',1)
open(f,'w').write(s)
